-- Visit Barichara — negocios reales investigados (fase 4), octubre 2026.
-- Fuentes: Google, Google Maps, TripAdvisor, Civitatis, GetYourGuide, Airbnb
-- Experiences, Rezdy y sitios oficiales — el link exacto de cada uno queda
-- en su columna source_url. Ningún dato de contacto fue inventado: donde no
-- se pudo verificar, el campo queda en null.
--
-- Todo entra con active = false (borrador) para que se revise desde /admin
-- antes de publicar. Los negocios genéricos de la carga anterior que no se
-- pudieron reconfirmar con esta investigación quedan desactivados al final
-- de este archivo (no se borran, solo se ocultan).
--
-- Ejecutar una sola vez, después de supabase/migration_03_website_instagram_source.sql.

-- ===================== HOTELES (15) =====================
on conflict (slug) do nothing;

-- ===================== RESTAURANTES (15) =====================
on conflict (slug) do nothing;

-- ===================== EXPERIENCIAS Y TOURS (14) =====================
on conflict (slug) do nothing;

-- ===================== TALLERES (3), TRANSPORTE (2), EVENTOS (1), COMERCIOS (1) =====================
on conflict (slug) do nothing;

-- ===================== Desactivar negocios genéricos no reconfirmados =====================
-- De la carga inicial ("15 mejores" sin verificación profunda): se mantienen
-- en la base de datos pero ocultos, por si luego se quieren reconfirmar o
-- contactar igual. No se borran.
update public.businesses set active = false
where slug in (
  'hotel-terra-barichara','casa-oniri','posada-villa-paula','la-juanita-hostel','corata','achiotte',
  'restaurante-terra','la-puerta-secret-kitchen','epice','frenchut','gringo-mikes','mija','el-puntal'
);
